        (Z_to_bv 64 (tl + 256 * mtl)) r25 y19 (Z_to_bv 64 2147450880) r28 r29 r30 r31) (only parsing).

  (* [comment removed for export] *)
  Notation Z32M mm :=
    (Z4SF' mm (SPA w40 w168 w176 w184 w192 w200 w208 (Z_to_bv 64 (DST + Qe)) w224 w232 w240 w248 (Z_to_bv 64 (SS + O + 8))
                   w264 w272 w280 w288 (Z_to_bv 64 tl) w304 (Z_to_bv 64 (DT + 4)) j0 j1) bd4) (only parsing).

  (* [comment removed for export] *)
  Hypothesis K32 : forall mm' (z1 z5 z7 z8 z11 z14 z15 z16 z17 z25 z29 z30 z31 : word),
    Z32M mm' ->
    evtF asegs RNG POST (ZC 0x8b714 mm' z1 z5 (Z_to_bv 64 tl) z7 z8 z11 z14 z15 z16 z17 y9 z25 w200 z29 z30 z31).

