                        w232 w240 w248 w264 w272 w280 w288 w304 j0 j1 bd4 K32) (only parsing).

  Lemma z32b_ff : 0x10007fff8000 <= SPF /\ SP <= 2^47 /\ ATOP + 4096 <= lo /\ lo + 8192 <= SP.
