  (* [comment removed for export] *)
  Lemma z32_join4 : forall p pt nb B flag mm (zf cw x5 x7 x8 x17 x21 x25 x26 x31 : word),
    Z32M mm -> DST <= p <= DST + Qe -> 0 <= nb <= pt -> nb <= 8 -> pt + 8 <= Lk -> 0 <= B <= 64 ->
    (flag = 0 \/ (flag = 1 /\ B <= 7)) ->
    (forall p' pt' B' mm' (cw' x5' x7' x8' x11' x16' x17' x21' x25' x26' x31' : word),
       Z32M mm' -> p < p' <= DST + Qe -> 0 <= pt' -> (pt' = 0 \/ pt' + 8 <= Lk) -> 0 <= B' <= 64 ->
       evtF asegs RNG POST (ZL 0x8ae38 mm' (Z_to_bv 64 B') x5' cw' x7' x8' x11' zf (Z_to_bv 64 p') x16' x17' x21'
                               (Z_to_bv 64 (SS + O + pt')) x25' x26' (Z_to_bv 64 64) (Z_to_bv 64 (DST + Qe - 7))
                               (Z_to_bv 64 (64 - tl)) x31')) ->
    evtF asegs RNG POST (ZL 0x8ae74 mm (Z_to_bv 64 B) x5 cw x7 x8 (Z_to_bv 64 flag) zf (Z_to_bv 64 p) (Z_to_bv 64 nb) x17 x21
                            (Z_to_bv 64 (SS + O + pt)) x25 x26 (Z_to_bv 64 64) (Z_to_bv 64 (DST + Qe - 7))
